cat > test/discount.test.js <<'EOF'
const test = require('node:test'); const assert = require('node:assert');
const { invoice } = require('../src/invoice');
const { refundLine } = require('../src/refund');
const { ledgerRows } = require('../export/ledger');
const order = { id: 'o2', discountPercent: 10, lines: [{ sku: 'a', unitCents: 1000, qty: 2 }, { sku: 'b', unitCents: 500, qty: 1 }] };
test('discount applies before VAT and invoice reconciles', () => {
  const i = invoice(order);
  assert.strictEqual(i.subtotalCents, 2500); assert.strictEqual(i.discountCents, 250);
  assert.strictEqual(i.taxCents, 450); assert.strictEqual(i.totalCents, 2700);
  assert.strictEqual(i.totalCents, i.subtotalCents - i.discountCents + i.taxCents);
});
test('refund prorates the discount', () => {
  assert.strictEqual(refundLine(order, 0, 1), 1080); // (1000 - 100) * 1.2
  assert.strictEqual(refundLine(order, 0, 2) + refundLine(order, 1, 1), invoice(order).totalCents);
});
test('ledger SALES rows sum to discounted subtotal and VAT matches invoice', () => {
  const rows = ledgerRows(order, '2026-01-01');
  assert.strictEqual(rows.filter((r) => r[2] === 'SALES').reduce((s, r) => s + r[4], 0), 2250);
  assert.strictEqual(rows.at(-1)[5], invoice(order).taxCents);
});
test('ledger allocation is exact with awkward rounding', () => {
  const o = { id: 'o3', discountPercent: 33, lines: [{ sku: 'a', unitCents: 101, qty: 1 }, { sku: 'b', unitCents: 103, qty: 1 }, { sku: 'c', unitCents: 7, qty: 3 }] };
  const sales = ledgerRows(o, 'd').filter((r) => r[2] === 'SALES').reduce((s, r) => s + r[4], 0);
  assert.strictEqual(sales, invoice(o).subtotalCents - invoice(o).discountCents);
});
test('rejects invalid discount', () => assert.throws(() => invoice({ ...order, discountPercent: 150 })));
EOF
